                    return Err((
                        RpcErrorResponse::ResourceUnavailable,
                        "Execution layer not synced",
                    ));
                }
                Err(e) => {
                    debug!(
                        ?peer_id,
                        request_root = ?root,
                        error = ?e,
                        "Error fetching block for peer"
                    );
                }
            }
        }
        log_results(peer_id, requested_blocks, send_block_count);

